-- The SOLIDSHRED code key (Code keys -> Milling -> SOLIDSHRED), from the ISCAR
-- e-catalog's SOLIDSHRED families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.solidshred', $ck${"title": "SOLIDSHRED code key – solid carbide roughing endmills", "subtitle": "Solid carbide roughing endmills with chip splitting and serrated cutting edges for high metal removal rates", "example": "ECR-B4M 10-20C10-72", "decoder": "solidshred", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "ECR", "rows": [{"code": "ECR", "meaning": "Roughing endmill"}, {"code": "ERF", "meaning": "Roughing endmill with a 3xD relieved neck for alloy steel"}, {"code": "ERC", "meaning": "Roughing endmill with a 3xD relieved neck for aluminum"}, {"code": "EBRF", "meaning": "Long ball nose roughing endmill (up to 55 HRC)"}, {"code": "ECP", "meaning": "Endmill with chip splitting cutting edges"}]}, {"key": "t-helix", "title": "Helix", "rows": [{"code": "A", "meaning": "30° helix"}, {"code": "B", "meaning": "45° helix"}, {"code": "E", "meaning": "38° helix"}, {"code": "T", "meaning": "20° helix"}]}, {"key": "t-flutes", "title": "Number of flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-length", "title": "Length", "rows": [{"code": "L", "meaning": "Long, with a 3xD relieved neck"}, {"code": "M", "meaning": "Medium length"}, {"code": "MF", "meaning": "Medium length, for materials up to 65 HRC"}, {"code": "S", "meaning": "Short"}, {"code": "X", "meaning": "Extra long"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-apmx", "title": "Cutting length", "rows": [{"code": "##", "meaning": "Cutting length in mm"}]}, {"key": "t-neck", "title": "Neck (reach) length", "rows": [{"code": "/##", "meaning": "Length to the neck end in mm"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}, {"code": "W", "meaning": "Weldon shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-corner", "title": "Corner", "rows": [{"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (R02 = 0.2 mm)"}, {"code": "RP#.#", "meaning": "Programmed radius (Rg) for CAM"}]}, {"key": "t-chamfer", "title": "Corner chamfer", "rows": [{"code": "CH##", "meaning": "Corner chamfer x10 (CH05 = 0.5 mm)"}]}, {"key": "t-line", "title": "Line (before the overall length)", "rows": [{"code": "A", "meaning": "For aluminum"}, {"code": "DA", "meaning": "Line DA (aluminum) (see the catalog)"}, {"code": "M", "meaning": "Line M (see the catalog)"}, {"code": "S", "meaning": "Line S (chip splitting) (see the catalog)"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "C", "meaning": "With coolant holes / channels"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
